using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Text;
using TMPro;
using UnityEditor;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;
using Object=UnityEngine.Object;
public static class GridShiftV12Checks {
 static readonly StringBuilder log=new StringBuilder();static int expectedEmployees;
 public static bool Enabled=>SessionState.GetBool("V12Suite",false);
 public static void Batch(){SessionState.SetBool("V12Suite",true);GridShiftV11Checks.Batch();}
 static void Check(bool ok,string message){log.AppendLine((ok?"PASS ":"FAIL ")+message);Directory.CreateDirectory("Docs/Validacao12");File.WriteAllText("Docs/Validacao12/scenarios.txt",log.ToString());if(!ok)throw new Exception(message);}
 public static IEnumerator Interface(GridShiftNativeOperations ops,PlayerMovement player,string name){yield return new WaitForSecondsRealtime(.8f);var r=ops.GetComponent<RectTransform>();var parent=(RectTransform)r.parent;var coverage=Vector2.Scale(r.rect.size,new Vector2(r.localScale.x,r.localScale.y));Check(Mathf.Abs(coverage.x/parent.rect.width-.95f)<.01f&&Mathf.Abs(coverage.y/parent.rect.height-.95f)<.01f,name+": painel ocupa 95% das duas dimensões da superfície real");ops.Show("Funcionários");yield return new WaitForSecondsRealtime(.8f);var nav=ops.transform.Find("Abas");var button=nav.GetComponentsInChildren<Button>().First(b=>b.name=="Funcionários");if(name=="computer"&&expectedEmployees>0)Check(DeliveryManager.Instance.Company.Employees==expectedEmployees&&ops.GetComponentsInChildren<TMP_Text>().Any(t=>t.text=="Funcionários ("+expectedEmployees+")"),"computador mostra a contratação feita no tablet após salvar e carregar");Check(button.GetComponentInChildren<TMP_Text>().text=="Funcionários",name+": aba mantém nome Funcionários");var scroll=ops.GetComponentInChildren<ScrollRect>();Check(scroll.content.rect.height>scroll.viewport.rect.height,name+": lista longa usa rolagem");scroll.OnScroll(new PointerEventData(EventSystem.current){scrollDelta=new Vector2(0,-5)});yield return null;Check(scroll.verticalNormalizedPosition<.99f,name+": roda do mouse desloca ScrollRect nativo");ops.Show("Upgrades");yield return new WaitForSecondsRealtime(.3f);GridShiftV11Capture.Save("v12-"+name,player.CameraTransform.GetComponent<Camera>());ops.Show("Visão Geral");}
 public static void Missions(DeliveryManager m){var company=m.Company;var original=JsonUtility.FromJson<CompanyCampaignState>(JsonUtility.ToJson(company.State));var orders=m.orders.ToList();float cash=m.Money;var levels=m.Progression.levels.Select(x=>new UpgradeLevel{id=x.id,level=x.level}).ToList();try{var state=company.State;var missions=company.Missions;var first=missions.First;first.step=11;Check(!missions.Claim(first.id,out _),"contador inicial 11/12 sem entrega real não concede bônus");var fake=new DeliveryOrder{id=Guid.NewGuid().ToString("N"),weightKg=5,requestId="mission:first-contract",status=DeliveryStatus.Transporting};m.orders.Add(fake);first.orderId=fake.id;Check(!missions.RequirementsMet(first)&&!missions.Claim(first.id,out _),"entrega em transporte não conta como concluída");m.RestoreTracking("veículo-inexistente",fake.id);Check(m.SelectedId==null&&m.TrackedVehicleId==null,"referência de veículo ausente encerra rastreamento com segurança");fake.status=DeliveryStatus.Completed;missions.Tick();Check(first.status==CompanyMissionStatus.AwaitingConfirmation&&!first.rewardClaimed,"entrega concluída aguarda confirmação sem recompensa antecipada");Check(missions.Claim(first.id,out _),"confirmação concede bônus da missão inicial");float paid=m.Money;Check(!missions.Claim(first.id,out _)&&m.Money==paid,"segunda confirmação não repete recompensa");
 var expansion=state.missions.First(x=>x.id=="expansion");missions.Tick();state.reputation=40;m.orders.Add(new DeliveryOrder{id=Guid.NewGuid().ToString("N"),weightKg=5,status=DeliveryStatus.Completed});m.orders.Add(new DeliveryOrder{id=Guid.NewGuid().ToString("N"),weightKg=5,status=DeliveryStatus.Completed});Check(!missions.RequirementsMet(expansion)&&!missions.Claim(expansion.id,out _),"três entregas e reputação não substituem especialista e upgrade");m.Progression.Restore(new List<UpgradeLevel>{new UpgradeLevel{id="fleet",level=1}});Check(!missions.RequirementsMet(expansion),"upgrade sozinho não conclui missão composta");Check(company.Employee("rui",true,out _),"contratação real de especialista utiliza sistema financeiro");missions.Tick();Check(expansion.status==CompanyMissionStatus.AwaitingConfirmation&&missions.ProgressText(expansion).Contains("Especialista contratado: 1/1"),"todos os requisitos individualizados liberam confirmação");Check(missions.Claim(expansion.id,out _),"missão composta concede recompensa somente após confirmar");
 var capture=m.GetComponent<DeliveryPersistence>().Capture();var path=Path.GetFullPath("Temp/v12-mission-state.json");Check(DeliverySaveStore.WriteAt(path,capture)&&DeliverySaveStore.ReadAt(path,out var saved,out _),"estado da missão é salvo e lido pelo armazenamento versionado");DeliverySaveStore.ReadAt(path,out saved,out _);company.Initialize(saved.company,false);float before=m.Money;Check(company.Missions.First.rewardClaimed&&!company.Missions.Claim("expansion",out _)&&m.Money==before,"estado e recompensa única sobrevivem à restauração");
 var stale=JsonUtility.FromJson<CompanyCampaignState>(JsonUtility.ToJson(original));var old=stale.missions.First(x=>x.id=="expansion");old.status=CompanyMissionStatus.Completed;old.step=999;old.rewardClaimed=false;company.Initialize(stale,false);Check(old.status!=CompanyMissionStatus.Completed&&!company.Missions.Claim(old.id,out _),"migração de campanha v1 não confia em contador ou status de conclusão antigos");
 }finally{m.RestoreEconomy(cash,orders,null);m.Progression.Restore(levels);company.Initialize(original,false);m.StopTracking();}Check(company.State.version==2,"migração usa versão 2 da campanha mantendo formato dos slots");}
 public static IEnumerator EmployeeLabel(GridShiftNativeOperations ops,DeliveryManager m,PlayerMovement player){ops.Show("Funcionários");yield return new WaitForSecondsRealtime(.8f);var button=ops.transform.Find("Abas").GetComponentsInChildren<Button>().First(b=>b.name=="Funcionários");int old=m.Company.Employees;var hire=ops.GetComponentsInChildren<Button>().First(b=>b.name=="Contratar"&&b.gameObject.activeInHierarchy);hire.onClick.Invoke();yield return new WaitForSecondsRealtime(1);Check(m.Company.Employees==old+1&&button.GetComponentInChildren<TMP_Text>().text=="Funcionários","contratação pelo tablet altera contador sem sobrescrever categoria");expectedEmployees=m.Company.Employees;}
 public static void LoopRoute(DeliveryManager m){var root=new GameObject("V12LoopFixture");var saved=m.points;try{Transform At(string name,Vector3 at){var g=new GameObject(name);g.transform.SetParent(root.transform);g.transform.position=at+Vector3.right*5000;return g.transform;}var vertices=new[]{Vector3.zero,Vector3.forward*100,new Vector3(100,0,100),Vector3.right*100};var routes=new TrafficRoute[4];for(int i=0;i<4;i++){routes[i]=At("Lane-"+i,Vector3.zero).gameObject.AddComponent<TrafficRoute>();routes[i].pontos=new[]{At("Start",vertices[i]),At("End",vertices[(i+1)%4])};}var p=At("Pickup",Vector3.forward*10).gameObject.AddComponent<DeliveryPoint>();p.id="v12-loop";p.route=routes[0];p.accessible=true;p.vehicleStop=p.transform;m.points=saved.Concat(new[]{p}).ToArray();var body=At("Vehicle",Vector3.forward*50).gameObject;var box=body.AddComponent<BoxCollider>();box.size=new Vector3(2,2,4);box.center=Vector3.up;var car=body.AddComponent<TrafficCar>();car.ResetRoute(routes[0]);var vehicle=body.AddComponent<CompanyVehicle>();vehicle.Configure(m,"V12-fixture",FleetKind.Car,200);Check(vehicle.Assign(new DeliveryOrder{id=Guid.NewGuid().ToString("N"),weightKg=5,pickupId=p.id,destinationId=p.id}),"coleta atrás exige volta pelo grafo dirigido");var points=new List<Vector3>();Check(vehicle.LoopDeparture&&GridShiftTrackedRoute.Build(vehicle,points)&&points.Count>=8&&points[1].z>body.transform.position.z&&points.Last()==p.Stop,"trajeto em laço percorre ruas conectadas sem cortar de volta para a coleta");car.RestoreLogicalRoute(routes[0],1,p.Stop-Vector3.forward*2,Quaternion.identity);typeof(CompanyVehicle).GetField("loopDeparture",BindingFlags.NonPublic|BindingFlags.Instance).SetValue(vehicle,false);Check(GridShiftTrackedRoute.Build(vehicle,points)&&points.Count==2,"ao retornar à via de coleta o mapa não desenha outra volta");}finally{m.points=saved;Object.DestroyImmediate(root);}}
 public static void Trace(){var m=DeliveryManager.Instance;if(m==null)return;string text="TIME "+Time.time+"\n";foreach(var c in TrafficCar.Active.Where(c=>c!=null))text+=c.name+" "+c.transform.position+" speed="+c.VelocidadeAtual+" "+c.DiagnosticDetail+"\n";foreach(var v in m.fleet.Where(v=>v!=null))text+="FLEET "+v.id+" "+v.state+" next="+v.driver.NextPoint+" target="+v.Target?.id+" order="+v.Order?.id+"\n";File.AppendAllText("Docs/Validacao12/traffic-runtime-trace.txt",text);}
 public static void Route(DeliveryManager m,CompanyVehicle v){LoopRoute(m);m.TrackVehicle(v.id);var points=new List<Vector3>();Check(GridShiftTrackedRoute.Build(v,points)&&Vector3.Distance(points.Last(),v.Target.Stop)<.01f,"rota acompanhada termina no alvo real de coleta ou descarga");var before=v.CurrentPath;typeof(CompanyVehicle).GetMethod("Go",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(v,new object[]{v.Target});Check(before!=v.CurrentPath&&GridShiftTrackedRoute.Build(v,points),"recalcular substitui trajeto e atualiza os pontos exibidos");m.StopTracking();Check(GridShiftTrackedRoute.Vehicle(m)==null&&v.Order!=null,"parar acompanhamento remove traçado sem cancelar entrega ou veículo");m.TrackVehicle(v.id);}
}
